SELECT s1.`c0` AS `id`, s1.`c1` AS `city` FROM (SELECT s2.`c0` AS `c0`, s2.`c4` AS `c1` FROM (SELECT s3.`c0` AS `c0`, s3.`c1` AS `c1`, s3.`c2` AS `c2`, s3.`c3` AS `c3`, s3.`c4` AS `c4` FROM (SELECT s4.`c0` AS `c0`, s4.`c1` AS `c1`, s4.`c2` AS `c2`, s5.`c0` AS `c3`, s5.`c1` AS `c4` FROM (SELECT `id` AS `c0`, `customer` AS `c1`, `amount` AS `c2` FROM `orders`) AS s4 CROSS JOIN (SELECT `name` AS `c0`, `city` AS `c1` FROM `customers`) AS s5) AS s3 WHERE ((CAST(20 AS BIGINT) < s3.`c2`) IS TRUE)) AS s2) AS s1
